SELECT t.id, t.status, t.follow_ups, e.id, e.requester_branch_id, rb.name, e.medication_id, COALESCE(m.brand_name || ' ' || m.strength || ' ' || m.dosage_form, ''), e.raw_request, e.quantity, o.sent_at FROM enquiry_targets t JOIN enquiries e ON e.id = t.enquiry_id JOIN branches rb ON rb.id = e.requester_branch_id LEFT JOIN medications m ON m.id = e.medication_id JOIN outbox_messages o ON o.target_id = t.id AND o.kind = 'enquiry' AND o.status = 'sent' WHERE t.branch_id = $1 ORDER BY o.sent_at DESC, t.id LIMIT $2 OFFSET $3
